#include "goal1_native_endpoint_invariant.hpp"
#include <iostream>
#include <iomanip>
#include <cstdlib>
#include <string>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;namespace ei=cs::native_endpoint_invariant;
Real Read(){std::string s;if(!(std::cin>>s))throw std::runtime_error("short invariant endpoint input");char*e;Real v=std::strtod(s.c_str(),&e);if(*e||!std::isfinite(v))throw std::runtime_error("bad invariant endpoint token");return v;}
void Array(const std::vector<Real>&v){std::cout<<"[";for(std::size_t j=0;j<v.size();++j)std::cout<<(j?",":"")<<v[j];std::cout<<"]";}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;std::cout<<std::setprecision(17);try{bool verify=argc>1&&std::string(argv[1])=="verify";while(std::cin>>std::ws,std::cin.peek()!=EOF){int id=Read();Real x[3];for(auto&v:x)v=Read();h::Z4cJet<Real>empty{};auto u=cs::typed_support::Map<Real>(empty,[](int,Real){return Read();});h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});auto p=descriptor.At(x[0],x[1],x[2]);auto base=ei::Evaluate(u,p,x);auto slots=cs::native_endpoint_completion::Unknowns();std::cout<<"{\"id\":"<<id<<",\"residual\":";Array(base.residual);std::cout<<",\"rhs\":";Array(std::vector<Real>(base.rhs.begin(),base.rhs.end()));std::cout<<",\"first\":[";for(int j=0;j<13;++j){if(j)std::cout<<",";Array(std::vector<Real>(base.first[j],base.first[j]+3));}std::cout<<"]";
 if(!verify){std::vector<std::vector<Real>>columns;for(int slot:slots){auto shifted=cs::typed_support::Map<Real>(u,[&](int n,Real v){return v+(slot==n?1:0);});auto r=ei::Evaluate(shifted,p,x);for(std::size_t j=0;j<r.residual.size();++j)r.residual[j]-=base.residual[j];columns.push_back(r.residual);}std::vector<Real>delta(184);for(int slot:slots)delta[slot]=.013*std::sin(Real(1+3*slot+id));auto shifted=cs::typed_support::Map<Real>(u,[&](int n,Real v){return v+delta[n];});auto r=ei::Evaluate(shifted,p,x);Real error=0,scale=1;for(std::size_t j=0;j<r.residual.size();++j){Real predicted=base.residual[j];for(std::size_t k=0;k<slots.size();++k)predicted+=columns[k][j]*delta[slots[k]];error=std::max(error,std::abs(predicted-r.residual[j]));scale=std::max(scale,std::abs(r.residual[j]));}std::cout<<",\"affine_relative\":"<<error/scale<<",\"unknowns\":[";for(std::size_t j=0;j<slots.size();++j)std::cout<<(j?",":"")<<slots[j];std::cout<<"],\"jacobian_columns\":[";for(std::size_t j=0;j<columns.size();++j){if(j)std::cout<<",";Array(columns[j]);}std::cout<<"]";
 }else{auto again=ei::Evaluate(u,p,x,.123);Real error=0;for(std::size_t j=0;j<base.residual.size();++j)error=std::max(error,std::abs(base.residual[j]-again.residual[j]));std::cout<<",\"unprovided_higherjet_invariance\":"<<error;}
 std::cout<<"}"<<std::endl;
 }}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
